-- PT117-S4-Q25. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT117-S4-Q25$batch03$ AND q.stimulus=$batch03$A certain medication that is frequently prescribed to lower a patient’s cholesterol level is generally effective. A recent study of 1,000 subjects ranging widely in age indicates, however, that the cholesterol level of someone taking the medication is typically 12 to 15 percent higher than the average for that person’s age group.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to explain how both of the claims made above could be true?$batch03$ AND q.correct_choice=$batch03$D$batch03$) THEN RAISE EXCEPTION 'Question changed: PT117-S4-Q25'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT117-S4-Q25$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT117-S4-Q25'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT117-S4-Q25$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$The medication generally lowers cholesterol.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$People taking it typically have cholesterol 12 to 15 percent above the average for their age?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$Who takes this drug? People with high cholesterol. If they start far above average, the drug can lower them a lot and still leave them above average. Use numbers: start 30 percent above, drop by more than half that gap, finish 12 to 15 percent above.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find that users started well above average.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT117-S4-Q25$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Another drug being better does not explain why this one's users are above average.$batch03$), ($batch03$B$batch03$, $batch03$How often another drug is prescribed says nothing about this drug's users.$batch03$), ($batch03$C$batch03$, $batch03$Most high-cholesterol patients being on diets does not explain the cholesterol of the people who do take the drug.$batch03$), ($batch03$D$batch03$, $batch03$The drug goes only to people at least 30 percent above average. Lowering them to 12 to 15 percent above is a real effect, and it leaves them above average.$batch03$), ($batch03$E$batch03$, $batch03$The balance of high and low cholesterol in the population tells us nothing about the drug's users.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT117-S4-Q25$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
